  insert into public.skill_domains (id, code, program, name, description) values
    ('dom-ai', 'AI', 'ABC', 'AI-augmented decision-making', 'Using GenAI copilots and analytics to make faster, better-evidenced decisions in own role.'),
    ('dom-opex', 'OPEX', 'ABC', 'Data-driven OpEx improvement', 'Finding and delivering productivity, cost and quality improvements from own-function data.'),
    ('dom-comm', 'COMM', 'ABC', 'Commercial & green acumen', 'Value-chain, partnership and Green / SVP / HVA economics including CBAM readiness.'),
    ('dom-silo', 'SILO', 'ABC', 'Cross-silo leadership', 'Self-awareness, cross-functional collaboration and organisation design.'),
    ('dom-cust', 'CUST', 'ABC', 'Customer-centric innovation', 'Designing improvements from internal or external customer needs, by BU and channel.'),
    ('dom-chg', 'CHG', 'ABC', 'Change execution', 'Landing practical improvements in the flow of work and sustaining them.'),
    ('dom-bb', 'BB', 'BCD', 'Business building & entrepreneurship', 'Framing, validating and building new concepts as investable businesses.'),
    ('dom-fin', 'FIN', 'BCD', 'Commercial finance & investment casing', 'Business cases, pricing and best / worst case analysis for gate decisions.'),
    ('dom-green', 'GRN', 'BCD', 'Customer-centric & green business design', 'Designing propositions around validated customer and sustainability needs.'),
    ('dom-aistrat', 'AIS', 'BCD', 'AI-augmented strategy', 'Using AI to accelerate research, scenario design and strategic choices.'),
    ('dom-exec', 'EXP', 'BCD', 'Executive presence & storytelling', 'Pitching evidence and asks clearly to executive committees.'),
    ('dom-lead', 'LTC', 'BCD', 'Leading through change', 'Leading cross-BU teams through ambiguity and gate outcomes.');
  insert into public.skills (id, domain_id, code, name, description, critical, premium_eligible, level_descriptors) values
    ('sk-genai', 'dom-ai', 'AI-01', 'GenAI copilot practice', 'Uses approved GenAI tools to draft, analyse and decide in daily work.', true, true, '["Level 1 · Aware: understands concepts and vocabulary; applies with close guidance.","Level 2 · Practising: applies the skill in routine situations in own role with occasional support.","Level 3 · Proficient: applies independently in complex situations and coaches peers.","Level 4 · Leading: sets standards, redesigns work around the skill and delivers measured impact."]'::jsonb),
    ('sk-decision', 'dom-ai', 'AI-02', 'Evidence-based decision making', 'Frames decisions, weighs evidence and records rationale.', true, false, '["Level 1 · Aware: understands concepts and vocabulary; applies with close guidance.","Level 2 · Practising: applies the skill in routine situations in own role with occasional support.","Level 3 · Proficient: applies independently in complex situations and coaches peers.","Level 4 · Leading: sets standards, redesigns work around the skill and delivers measured impact."]'::jsonb),
