  insert into public.impact_contracts (id, enrollment_id, learner_id, manager_id, sponsor_id, title, objective_type, description, baseline_value, target_value, unit, target_thb, tools_applied, status, return_reason, mid_gate_decision, mid_gate_note, showcase_summary, validated_value_thb, validated_at, created_at, updated_at) values
    ('ic-nara', 'enr-nara', 'per-nara', 'per-kittipong', 'per-prasert', 'Lift dealer share of wallet in Central Region with AI lead scoring', 'share_of_wallet', 'Use AI lead scoring on the 120 active dealers in Central Region to prioritise weekly visits and offers. Practical improvement: a scored dealer list every Monday, a standard offer pack per segment, and a weekly review with the credit team.', 31, 36, '% share of wallet (top 40 dealers)', 4200000, 'SCG GenAI copilot; CRM export; dealer segmentation template from Lab Day 4', 'active', null, null, null, null, null, null, '2026-08-13T09:00:00+07:00', '2026-08-20T09:00:00+07:00'),
    ('ic-tanawat', 'enr-tanawat', 'per-tanawat', 'per-somsak', 'per-prasert', 'Reduce unplanned kiln downtime at Saraburi Line 2', 'productivity_per_fte', 'Daily downtime story with root-cause tags, GenAI-assisted shift handover and a weekly OpEx routine. Practical improvement: 15% fewer unplanned stops on Line 2.', 42, 36, 'unplanned stop hours per month', 3600000, 'Downtime log analytics; GenAI copilot for handover notes', 'mid_gate_review', null, null, null, null, null, null, '2026-08-13T09:00:00+07:00', '2026-09-12T09:00:00+07:00'),
    ('ic-boonchu', 'enr-boonchu', 'per-boonchu', 'per-somsak', 'per-prasert', 'Cut empty return trips from Saraburi to Bangkok depots', 'cost_to_serve', 'Use route data to pair outbound deliveries with backhaul loads.', 38, 30, '% empty return trips', null, 'Route planning export', 'returned', 'Add the THB value of the target and name the logistics partner who will confirm the baseline. The sprint scope is good.', null, null, null, null, null, '2026-08-13T09:00:00+07:00', '2026-09-08T09:00:00+07:00'),
    ('ic-arisa', 'enr-arisa', 'per-arisa', 'per-somsak', 'per-prasert', 'Switch two packaging categories to lower-CBAM-exposure suppliers', 'cost_to_serve', 'Re-quote two categories with green options and a total-cost model.', 100, 92, 'index of category cost (baseline = 100)', 2000000, 'Total-cost model; CBAM exposure calculator', 'validated', null, 'scale', 'Evidence shows 5% saving already on category 1. Scale to category 2.', 'Delivered THB 2.4M annualised saving across both categories with CBAM exposure reduced by 18%.', 2400000, '2026-07-31T09:00:00+07:00', '2026-04-23T09:00:00+07:00', '2026-07-31T09:00:00+07:00'),
    ('ic-jiraporn', 'enr-jiraporn', 'per-jiraporn', 'per-somsak', 'per-prasert', 'Reduce QA re-test cycle time for cement samples', 'sla_turnaround', 'Standard sample routing and a daily data story of re-test causes.', 3.2, 2, 'days re-test cycle time', 1100000, 'Lab data export; GenAI copilot for cause tagging', 'showcase_review', null, 'scale', 'On track; extend to second lab.', 'Cycle time down to 2.1 days; THB 1.1M avoided rework and overtime (annualised).', null, null, '2026-04-23T09:00:00+07:00', '2026-07-27T09:00:00+07:00'),
    ('ic-pim', 'enr-pim', 'per-pim', 'per-ratree', 'per-wanida', 'Automate invoice exception triage for BU finance teams', 'productivity_per_fte', 'Use GenAI to classify invoice exceptions and route them; agree a service level with two BU finance teams.', 210, 300, 'invoices processed per FTE per week', 1800000, 'SCG GenAI copilot; AP workflow export', 'manager_review', null, null, null, null, null, null, '2026-09-03T09:00:00+07:00', '2026-09-10T09:00:00+07:00'),
    ('ic-krit', 'enr-krit', 'per-krit', 'per-ratree', 'per-wanida', 'Cut service-desk resolution time with a knowledge copilot', 'sla_turnaround', 'Publish a copilot over approved runbooks and track first-contact resolution weekly.', 18, 12, 'hours mean time to resolve', 1500000, 'Runbook copilot; ticket analytics', 'sponsor_review', null, null, null, null, null, null, '2026-09-02T09:00:00+07:00', '2026-09-11T09:00:00+07:00'),
    ('ic-nok', 'enr-nok', 'per-nok', 'per-ratree', 'per-wanida', 'Reduce payroll query turnaround for plant HR teams', 'sla_turnaround', 'Draft only. Diagnostic still pending, so priority skills are not yet selected.', 5, 2, 'days to resolve payroll query', null, null, 'draft', null, null, null, null, null, null, '2026-09-09T09:00:00+07:00', '2026-09-09T09:00:00+07:00');
  insert into public.sprint_evidence (id, contract_id, week_no, title, note, metric_value, created_by, created_at) values
    ('ev-nara-w1', 'ic-nara', 1, 'Scored dealer list produced', 'First AI lead-scoring run on 120 dealers; top 40 identified. Baseline confirmed with credit team.', 31, 'per-nara', '2026-08-21T09:00:00+07:00'),
    ('ev-nara-w2', 'ic-nara', 2, 'Standard offer pack per segment', 'Three offer packs drafted with the copilot and reviewed by marketing.', 31.5, 'per-nara', '2026-08-28T09:00:00+07:00'),
    ('ev-nara-w3', 'ic-nara', 3, 'Weekly review with credit team started', 'Two dealers moved to prioritised credit terms; visit plan follows scores.', 32.4, 'per-nara', '2026-09-04T09:00:00+07:00'),
    ('ev-nara-w4', 'ic-nara', 4, 'Clinic 1 feedback applied', 'Coach suggested tracking share of wallet weekly rather than monthly. Dashboard now weekly.', 33.1, 'per-nara', '2026-09-11T09:00:00+07:00'),
    ('ev-tanawat-w1', 'ic-tanawat', 1, 'Downtime tagging live', 'All Line 2 stops now tagged with root cause.', 42, 'per-tanawat', '2026-08-21T09:00:00+07:00'),
    ('ev-tanawat-w2', 'ic-tanawat', 2, 'Handover notes with copilot', 'Shift handover written with the copilot; 20 minutes saved per shift.', 41, 'per-tanawat', '2026-08-28T09:00:00+07:00'),
    ('ev-tanawat-w3', 'ic-tanawat', 3, 'Weekly OpEx routine', 'Top 3 causes reviewed weekly with maintenance.', 39, 'per-tanawat', '2026-09-04T09:00:00+07:00'),
    ('ev-tanawat-w4', 'ic-tanawat', 4, 'Mid-gate evidence pack submitted', 'Unplanned stop hours trending to 37 hours per month. Requesting scale to Line 1.', 37.5, 'per-tanawat', '2026-09-12T09:00:00+07:00'),
    ('ev-pim-w1', 'ic-pim', 1, 'Exception categories defined', 'Nine categories agreed with two BU finance teams.', 210, 'per-pim', '2026-09-11T09:00:00+07:00');
  insert into public.challenge_themes (id, bu_id, title, description, set_by_id, year) values
    ('th-cbm-fuel', 'bu-cbm', 'Waste reduction & alternative fuels', 'Lower cost per tonne and carbon intensity through alternative fuels and waste-to-value.', 'per-prasert', 2026),
    ('th-cbm-dealer', 'bu-cbm', 'Dealer service excellence', 'Grow share of wallet and cut cost-to-serve across the dealer network.', 'per-prasert', 2026),
    ('th-cafi-auto', 'bu-cafi', 'Automation of transactional finance', 'Raise productivity per FTE and service levels with automation and analytics.', 'per-wanida', 2026),
