  insert into public.challenge_briefs (id, theme_id, bu_id, sponsor_id, title, challenge_type, problem_statement, success_metric, target_value_thb, constraints, status, cohort_id, committee_note, reviewed_by_id, reviewed_at, created_at, updated_at) values
    ('cb-fuel', 'th-cbm-fuel', 'bu-cbm', 'per-prasert', 'Raise alternative-fuel substitution at two kilns to 35%', 'cost', 'Fuel is the largest controllable cost per tonne. Substitution is stuck at 22% because supply of refuse-derived fuel is unreliable.', 'Fuel cost per tonne; substitution rate', 45000000, null, 'assigned', 'coh-bcd-l1', 'Approved. Strong P&L anchor for the turnaround.', 'per-chatchai', '2026-06-12T09:00:00+07:00', '2026-05-20T09:00:00+07:00', '2026-06-29T09:00:00+07:00'),
    ('cb-invoice', 'th-cafi-auto', 'bu-cafi', 'per-wanida', 'Touchless invoice processing for all BUs', 'productivity', 'Only 40% of invoices are processed without manual touch. BU finance teams escalate exceptions by email.', 'Touchless rate; cost per invoice', 18000000, null, 'assigned', 'coh-bcd-l1', 'Approved with a request to include a service-level commitment.', 'per-chatchai', '2026-06-12T09:00:00+07:00', '2026-05-22T09:00:00+07:00', '2026-06-29T09:00:00+07:00'),
    ('cb-pack', 'th-scgp-green', 'bu-scgp', 'per-suchada', 'Recyclable packaging line for B2B2C food brands', 'growth', 'Food brands ask for recyclable packaging but current offers do not meet cost targets.', 'New revenue; gross margin', 60000000, null, 'assigned', 'coh-bcd-l1', 'Approved.', 'per-chatchai', '2026-06-12T09:00:00+07:00', '2026-05-25T09:00:00+07:00', '2026-06-29T09:00:00+07:00'),
    ('cb-logistics', 'th-cbm-dealer', 'bu-cbm', 'per-prasert', 'Cut cost-to-serve in CBM dealer logistics by 15%', 'cost', 'Small, frequent dealer orders drive high delivery cost. No shared visibility between sales, logistics and dealers.', 'Cost-to-serve per tonne delivered', 35000000, 'Must work with existing transport partners; no new fleet capex in 2027.', 'committee_review', null, null, null, null, '2026-09-02T09:00:00+07:00', '2026-09-08T09:00:00+07:00'),
    ('cb-close', 'th-cafi-auto', 'bu-cafi', 'per-wanida', 'AI-assisted month-end close in five days', 'service', 'Month-end close takes nine working days; BU CFOs want five.', 'Working days to close; adjustments after close', 12000000, null, 'committee_review', null, null, null, null, '2026-09-04T09:00:00+07:00', '2026-09-09T09:00:00+07:00'),
    ('cb-cbam', 'th-cbm-fuel', 'bu-cbm', 'per-prasert', 'Low-carbon cement for CBAM export markets', 'growth', 'European customers will pay a premium for verified low-carbon cement from 2027 but SCG has no certified product.', 'Export revenue; premium per tonne', 80000000, null, 'approved', null, 'Approved. Program office to assign to BCD Batch 1/2027.', 'per-chatchai', '2026-09-11T09:00:00+07:00', '2026-08-28T09:00:00+07:00', '2026-09-11T09:00:00+07:00'),
    ('cb-ordering', 'th-cbm-dealer', 'bu-cbm', 'per-suchada', 'Dealer digital ordering and credit self-service', 'service', 'Dealers order by phone and LINE; credit checks take two days.', 'Order-to-confirm time; dealer satisfaction', null, null, 'returned', null, 'Add a THB target value and confirm which BU P&L owns the benefit. Sponsor and brief BU do not match.', 'per-ploy', '2026-09-10T09:00:00+07:00', '2026-09-01T09:00:00+07:00', '2026-09-10T09:00:00+07:00'),
    ('cb-hrbot', 'th-cafi-sla', 'bu-cafi', 'per-wanida', 'Shared-service copilot for HR and payroll queries', 'service', 'HR service desk answers 6,000 repeat queries a month by email.', 'Queries resolved by copilot; turnaround time', 6000000, null, 'draft', null, null, null, null, '2026-09-12T09:00:00+07:00', '2026-09-12T09:00:00+07:00'),
